   222|  const job = await getSeniorDeveloperJob(item.jobId);
   223|  if (!job) {
   224|    // Don't overwrite a verified item if the job was already completed and cleared.
   225|    if (item.status === 'verified') return;
   226|    item.status = 'blocked';
   227|    item.lastError = 'Worker job not found.';
