   294|/** Serialize state mutations so concurrent job completions can't race. */
   295|function enqueueWrite<T>(task: () => Promise<T>): Promise<T> {
   296|  const run = writeChain.then(task, task);
   297|  writeChain = run.then(
   298|    () => undefined,
   299|    () => undefined,
   300|  );
   301|  return run;
