   306|  patch: (job: ScheduledJobState, now: number) => ScheduledJobState,
   307|  now: number = Date.now(),
   308|): Promise<SchedulerState> {
   309|  return enqueueWrite(async () => {
   310|    const state = await getSchedulerState();
   311|    state.jobs[kind] = patch(state.jobs[kind], now);
   312|    await writeSchedulerState(state);
   313|    return state;
   314|  });
