   204|/**
   205| * Classify an owner command into an execution decision.
   206| *
   207| * - Non-destructive execution command → `autoExecute: true`, `systemMode: true`.
   208| * - Execution command touching a guarded category → `requiresApproval: true`,
   209| *   `autoExecute: false`, `systemMode: false`, with the exact categories named.
   210| * - Not an execution command → `isOwnerExecutionCommand: false` (caller routes normally).
   211| */
   212|export function classifyOwnerExecutionCommand(prompt: string): IVXOwnerExecutionDecision {
   213|  const normalized = normalize(prompt);
   214|  if (!normalized) {
   215|    return {
   216|      isOwnerExecutionCommand: false,
   217|      autoExecute: false,
   218|      requiresApproval: false,
   219|      approvalCategories: [],
   220|      reason: 'Empty prompt — no owner execution command detected.',
   221|      systemMode: false,
   222|      matchedTriggers: [],
   223|      safeCategories: [],
   224|    };
   225|  }
   226|
   227|  const matchedTriggers = detectTriggers(normalized);
   228|  const approvalCategories = detectApprovalCategories(normalized);
   229|  const safeCategories = detectSafeCategories(normalized);
   230|  const requiresApproval = approvalCategories.length > 0;
   231|  // A bare destructive imperative ("delete all user data", "disable auth") is
   232|  // itself an owner command, even without a generic execution trigger phrase.
   233|  const isOwnerExecutionCommand = matchedTriggers.length > 0 || requiresApproval;
   234|
   235|  if (!isOwnerExecutionCommand) {
   236|    return {
   237|      isOwnerExecutionCommand: false,
   238|      autoExecute: false,
   239|      requiresApproval,
   240|      approvalCategories,
   241|      reason: requiresApproval
   242|        ? `Command references a guarded action (${approvalCategories.map(labelFor).join(', ')}) but is not an explicit execution command; route normally and confirm before acting.`
   243|        : 'No execution trigger detected — route as a normal conversation/question.',
   244|      systemMode: false,
   245|      matchedTriggers,
   246|      safeCategories,
   247|    };
   248|  }
   249|
   250|  if (requiresApproval) {
   251|    return {
   252|      isOwnerExecutionCommand: true,
   253|      autoExecute: false,
   254|      requiresApproval: true,
   255|      approvalCategories,
   256|      reason: `Owner execution command requires explicit approval because it ${approvalCategories
   257|        .map(labelFor)
   258|        .join(' and ')}. Confirm the exact action before it runs.`,
   259|      systemMode: false,
   260|      matchedTriggers,
   261|      safeCategories,
   262|    };
   263|  }
   264|
   265|  const safeLane = safeCategories.length > 0
   266|    ? ` Auto-approval lane: safe ${safeCategories.map(safeLabelFor).join(', ')}.`
   267|    : '';
   268|  return {
   269|    isOwnerExecutionCommand: true,
   270|    autoExecute: true,
   271|    requiresApproval: false,
   272|    approvalCategories: [],
   273|    reason: `Owner execution command (${matchedTriggers.join(', ')}) is non-destructive — execute end-to-end (patch → test → commit → deploy → verify) without an approval prompt.${safeLane}`,
   274|    systemMode: true,
   275|    matchedTriggers,
   276|    safeCategories,
   277|  };
